  await check('each money tile shows the backend total of its currency and a split per book from the money totals',`(()=>{const [types,books]=${desk}.summaries,tile=(key,type,measure,word)=>{const own=types.groups.filter(g=>g.instrumentType===type),rows=[...document.querySelectorAll('#desk-tile-'+key+' .desk-tile-row')];if(!own.length)return rows.length===0&&document.querySelector('#desk-tile-'+key+' > .desk-tile-note').textContent==='No '+word+' in the selected books';const g=own[0],splits=[...rows[0].querySelectorAll('.desk-split')].map(s=>s.title);return own.length===1&&rows.length===1&&rows[0].querySelector('.kpi-value').title===g[measure]+' '+g.currency&&JSON.stringify(splits)===JSON.stringify(books.groups.filter(b=>b.instrumentType===type).sort((a,b)=>a.book.localeCompare(b.book)).map(b=>b.book+' · '+b[measure]+' '+b.currency));};return types.view.pivotConvention==='trading_blotter_money_totals_v1'&&books.view.pivotConvention==='trading_blotter_money_totals_v1'&&types.groups.some(g=>g.instrumentType==='future')&&tile('swapPv','financial_swap','presentValue','swaps')&&tile('futuresPnl','future','executionPnl','futures');})()`,`[...document.querySelectorAll('.desk-tile')].map(t=>t.innerText)`);
  await check('the positions tile counts the rows read and mixes them by the backend commodity and instrument type groups',`(()=>{const d=${desk},mix=d.summaries[2];return document.querySelector('#desk-tile-positions .kpi-value').firstChild.textContent===String(d.blotter.holdings.length)&&document.querySelectorAll('#desk-tile-positions .desk-legend li').length===mix.groups.length&&[...document.querySelectorAll('#desk-tile-positions .desk-legend b')].map(b=>Number(b.textContent)).sort().join()===mix.groups.map(g=>g.tradeCount).sort().join();})()`);
